let lang='fr';try{lang=localStorage.getItem('oustadi-v2-language')==='ar'?'ar':'fr'}catch{}
const state={role:'teacher',published:false,active:false,complete:false,format:'video',answer:null};
const $=s=>document.querySelector(s);const $$=s=>[...document.querySelectorAll(s)];const t=k=>copy[lang][k]??copy.fr[k]??k;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const lines=s=>esc(s).replace(/\n/g,'<br>');
function setLanguage(next){document.dispatchEvent(new Event('oustadi:language-start'));lang=next;document.documentElement.lang=next==='ar'?'ar-MA':'fr';document.documentElement.dir=next==='ar'?'rtl':'ltr';document.title=t('title');$('meta[name="description"]').content=t('description');$$('[data-i18n]').forEach(el=>{const value=t(el.dataset.i18n);el.replaceChildren(...value.split('\n').flatMap((part,i)=>i?[document.createElement('br'),document.createTextNode(part)]:[document.createTextNode(part)]))});$('#language').innerHTML=next==='fr'?'بالدارجة <span aria-hidden="true">↗</span>':'Français <span aria-hidden="true">↗</span>';$('#language').lang=next==='fr'?'ar-MA':'fr';$('#language').dir=next==='fr'?'rtl':'ltr';$('#nav').setAttribute('aria-label',next==='fr'?'Navigation':'التنقل');$('.journey-tabs').setAttribute('aria-label',next==='fr'?'Les trois étapes du parcours':'ثلاث مراحل فالمسار');$('.format-tabs').setAttribute('aria-label',next==='fr'?'Les formats pédagogiques':'أنواع الدروس');$$('.dialog-close').forEach(b=>b.setAttribute('aria-label',t('close')));$('.hero-art').setAttribute('aria-label',t('oneLesson'));$('.math-image')?.setAttribute('aria-label',next==='fr'?'Courbe et tangente illustratives':'رسم توضيحي لمنحنى ومماس');try{localStorage.setItem('oustadi-v2-language',lang)}catch{}renderJourney();renderLearning();document.dispatchEvent(new CustomEvent('oustadi:language',{detail:{lang}}));}
function renderJourney(){const role=state.role;$$('[data-role]').forEach(b=>{const selected=b.dataset.role===role;b.setAttribute('aria-selected',String(selected));b.tabIndex=selected?0:-1});const panel=$('#journey-panel');panel.setAttribute('aria-labelledby','tab-'+role);let left='',right='';
  if(role==='teacher'){
    left=`<h3>${lines(t('stageTeacherTitle'))}</h3><p>${esc(t('stageTeacherText'))}</p><button class="button ink" data-demo-action="${state.published?'center':'publish'}">${esc(t(state.published?'goReception':'publish'))}</button>`;
    right=`<div class="workspace-head"><strong>${esc(t('workspace'))}</strong><span class="pill ${state.published?'':'peach-pill'}">${esc(t(state.published?'published':'draft'))}</span></div><p class="curriculum-title">${esc(t('chapter'))}</p>${[['▷','video','videoDetail','04:20'],['▤','document','sheetDetail','PDF'],['✓','quiz','quizDetail','1 Q']].map(([g,k,d,n])=>`<div class="lesson-row"><span class="glyph" aria-hidden="true">${g}</span><div class="row-copy"><strong>${esc(t(k))}</strong><small>${esc(t(d))}</small></div><small>${n}</small></div>`).join('')}`;
  }else if(role==='center'){
    const action=!state.published?'teacher':state.active?'student':'activate';
    left=`<h3>${lines(t('stageCenterTitle'))}</h3><p>${esc(t('stageCenterText'))}</p><button class="button ink" data-demo-action="${action}">${esc(t(!state.published?'prepareFirst':state.active?'viewStudent':'activate'))}</button><p class="stage-hint">${esc(t('centerHint'))}</p>`;
    right=`<div class="workspace-head"><strong>${esc(t('receptionDesk'))}</strong><span>${esc(t('demoProvider'))}</span></div><div class="student-person"><span class="avatar" aria-hidden="true">SA</span><div><strong>${esc(t('studentName'))}</strong><small dir="auto">${esc(t('studentCode'))}</small></div></div><div class="access-row"><strong>${esc(t('lessonName'))}</strong><div><span>${esc(t('period'))}</span><span class="pill ${state.active?'':'peach-pill'}">${esc(t(state.active?'active':'waiting'))}</span></div></div>`;
  }else{
    left=`<h3>${lines(t('stageStudentTitle'))}</h3><p>${esc(t('stageStudentText'))}</p><button class="button ink" data-demo-action="${!state.active?'center':state.complete?'quiz':'complete'}">${esc(t(!state.active?'goCenter':state.complete?'tryQuiz':'markComplete'))}</button>`;
    right=`<div class="workspace-head"><strong>${esc(t('studentApp'))}</strong><span>${esc(t('demoProvider'))}</span></div>${state.active?`<p class="curriculum-title">${esc(t('welcomeStudent'))}</p><div class="student-mini"><p>${esc(t('continueLabel'))}</p><h4>${esc(t('lessonName'))}</h4><div class="mini-progress"><i style="width:${state.complete?100:38}%"></i></div><small>${esc(t(state.complete?'completed':'progress'))}${state.complete?'':' · 38 %'}</small></div><div class="lesson-row"><span class="glyph" aria-hidden="true">▤</span><div class="row-copy"><strong>${esc(t('fileShort'))}</strong><small>${esc(t('documentReady'))}</small></div></div>`:`<div class="locked-preview"><span aria-hidden="true">⌑</span><strong>${esc(t('lockedTitle'))}</strong><p>${esc(t('lockedText'))}</p></div>`}`;
  }
  panel.innerHTML=`<div class="panel-narrative">${left}</div><div class="panel-workspace">${right}</div>`;$('#journey-status').textContent=t(state.complete?'status3':state.active?'status2':state.published?'status1':'status0');document.dispatchEvent(new CustomEvent('oustadi:journey',{detail:{role:state.role,published:state.published,active:state.active,complete:state.complete}}));
}
function setRole(role,focus=false){state.role=role;renderJourney();if(focus)$('#tab-'+role).focus()}
function renderLearning(){const format=state.format;$$('[data-format]').forEach(b=>{const chosen=b.dataset.format===format;b.setAttribute('aria-selected',String(chosen));b.tabIndex=chosen?0:-1});const p=$('#learning-panel');p.setAttribute('aria-labelledby','format-'+format);let html=`<div class="learning-head"><span>${esc(t('sample'))}</span><span>${esc(t(format==='pdf'?'document':format))}</span></div>`;
  if(format==='video')html+=`<h3>${esc(t('videoPreviewTitle'))}</h3><p>${esc(t('videoPreviewText'))}</p><div class="video-example" aria-hidden="true"><span class="equation">f(x) = x²</span><span class="video-play">▷</span><i class="video-bar"></i></div><p class="sample-meta">${esc(t('videoPreviewNote'))}</p><button class="text-link" data-learning-action="student">${esc(t('seeStudent'))}</button>`;
  if(format==='pdf')html+=`<div class="sheet-title" style="margin-top:24px">${esc(t('sheetTitle'))}</div><div class="sheet-equation">f(x) = x² → f′(x) = 2x</div><div class="sheet-line">${esc(t('sheetRule'))}<small>${esc(t('sheetRuleDetail'))}</small></div><div class="sheet-line">${esc(t('sheetExercise'))}<small>${esc(t('sheetAnswer'))}</small></div><p class="sample-meta" style="margin-top:20px">${esc(t('sheetNote'))}</p>`;
  if(format==='quiz')html+=`<h3>${esc(t('quizTitle'))}</h3><div class="quiz-question">${esc(t('quizPrompt'))}</div><div class="quiz-options" role="group" aria-label="${esc(t('quizPrompt'))}">${['x','2x','x²'].map((a,i)=>`<button type="button" data-answer="${i}" aria-pressed="${state.answer===i}" class="${state.answer===i?'selected':''}">${a}</button>`).join('')}</div><p class="quiz-result" role="status" aria-live="polite">${esc(t(state.answer===null?'quizHint':state.answer===1?'quizCorrect':'quizWrong'))}</p>${state.answer!==null?`<button class="text-link" data-learning-action="retry">${esc(t('quizReset'))} ↺</button>`:''}`;
  p.innerHTML=html;document.dispatchEvent(new CustomEvent('oustadi:learning',{detail:{format:state.format,answer:state.answer}}));
}
function tabKeyboard(event,selector,select){const keys=['ArrowLeft','ArrowRight','Home','End'];if(!keys.includes(event.key))return;const items=$$(selector);const current=items.indexOf(event.target);if(current<0)return;event.preventDefault();let n=current;const delta=(event.key==='ArrowRight'?1:-1)*(lang==='ar'?-1:1);if(event.key==='Home')n=0;else if(event.key==='End')n=items.length-1;else n=(n+delta+items.length)%items.length;select(items[n]);items[n].focus()}
$('.journey-tabs').addEventListener('click',e=>{const b=e.target.closest('[data-role]');if(b)setRole(b.dataset.role)});$('.journey-tabs').addEventListener('keydown',e=>tabKeyboard(e,'[data-role]',b=>setRole(b.dataset.role)));
$('#journey-panel').addEventListener('click',e=>{const b=e.target.closest('[data-demo-action]');if(!b)return;switch(b.dataset.demoAction){case'publish':state.published=true;setRole('center',true);break;case'activate':if(state.published){state.active=true;setRole('student',true)}break;case'complete':state.complete=true;renderJourney();$('#journey-panel').focus();break;case'quiz':state.format='quiz';renderLearning();$('#apprendre').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});$('#format-quiz').focus({preventScroll:true});break;default:setRole(b.dataset.demoAction,true)}});
$('#reset-demo').addEventListener('click',()=>{Object.assign(state,{role:'teacher',published:false,active:false,complete:false});renderJourney();$('#tab-teacher').focus()});
$('.format-tabs').addEventListener('click',e=>{const b=e.target.closest('[data-format]');if(b){state.format=b.dataset.format;renderLearning()}});$('.format-tabs').addEventListener('keydown',e=>tabKeyboard(e,'[data-format]',b=>{state.format=b.dataset.format;renderLearning()}));
$('#learning-panel').addEventListener('click',e=>{const answer=e.target.closest('[data-answer]');if(answer){state.answer=Number(answer.dataset.answer);renderLearning();$(`[data-answer="${state.answer}"]`).focus()}const action=e.target.closest('[data-learning-action]');if(action?.dataset.learningAction==='retry'){state.answer=null;renderLearning();$('[data-answer="0"]').focus()}if(action?.dataset.learningAction==='student'){setRole('student');$('#parcours').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});$('#tab-student').focus({preventScroll:true})}});
$('#darija-story').addEventListener('click',()=>$('#story-dialog').showModal());
$('#language').addEventListener('click',()=>setLanguage(lang==='fr'?'ar':'fr'));
const menu=$('.menu-toggle');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));$('#nav').classList.toggle('open',open)});$('#nav').addEventListener('click',e=>{if(e.target.closest('a,button')&&!e.target.closest('#language')){menu.setAttribute('aria-expanded','false');$('#nav').classList.remove('open')}});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&menu.getAttribute('aria-expanded')==='true'){menu.setAttribute('aria-expanded','false');$('#nav').classList.remove('open');menu.focus()}});
function updateProvider(){const name=$('#provider-name').value.trim()||t('demoProvider');$('#provider-display').textContent=name;const words=name.split(/\s+/);$('#provider-monogram').textContent=words.slice(0,2).map(s=>[...s][0]).join('').toLocaleUpperCase().slice(0,3)}$('#provider-name').addEventListener('input',updateProvider);$$('[name="provider-color"]').forEach(r=>r.addEventListener('change',()=>$('.provider-screen').style.setProperty('--provider',({mulberry:'#68234F',blue:'#274C77',green:'#245C4B'})[r.value])));
$$('[data-open-brief]').forEach(b=>b.addEventListener('click',()=>$('#brief-dialog').showModal()));$('#about-preview').addEventListener('click',()=>$('#about-dialog').showModal());$$('[data-close]').forEach(b=>b.addEventListener('click',()=>b.closest('dialog').close()));$$('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target!==d)return;const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}));
$('#brief-form').addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget;if(!form.reportValidity())return;const data=new FormData(form);const text=['Oustadi Plus — '+t('briefTag'),'',[''+t('yourRole')+': '+t(data.get('role')==='center'?'roleCenter':'roleTeacher'),t('yourName')+': '+String(data.get('name')).trim(),t('city')+': '+String(data.get('city')).trim(),t('studentsCount')+': '+data.get('students'),t('priority')+': '+String(data.get('priority')).trim()].join('\n'),'',t('briefIntro'),t('briefPrivacy'),new URL('./',location.href).href].join('\n');const blob=new Blob(['\uFEFF'+text],{type:'text/plain;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='oustadi-plus-fiche-pilote.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$('#brief-result').textContent=t('briefSuccess');$('#brief-result').scrollIntoView({block:'nearest'})});
